from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection

with open('libmonosgen-2.0.so.debug', 'rb') as f:
    elf = ELFFile(f)
    symtab = elf.get_section_by_name('.symtab')
    addrs = [0x2f4b20, 0x2f4c84]
    for target in addrs:
        best = None
        for sym in symtab.iter_symbols():
            if sym['st_info']['type'] in ('STT_FUNC', 'STT_OBJECT'):
                start = sym['st_value']
                size = sym['st_size']
                if start <= target < start + size:
                    if best is None or start > best['st_value']:
                        best = sym
        if best:
            print(f'0x{target:x}: {best.name} + 0x{target - best[\"st_value\"]:x}')
        else:
            print(f'0x{target:x}: (no enclosing symbol found)')
"

